  '1395774463676649502': { name: 'leads-peru-valiosos',       target: 'Leads',    country: 'PE' },
  '1395774501773639710': { name: 'leads-mexico-valiosos',     target: 'Leads',    country: 'MX' },
  '1395774545368973506': { name: 'leads-colombia-valiosos',   target: 'Leads',    country: 'CO' },
  '969325696499482654':  { name: 'registros-colombia',        target: 'Leads',    country: 'CO' },
  '1344382061363859599': { name: 'leads-recovery-nuevos',     target: 'Recovery', country: 'AUTO' },
  '1346134811466665984': { name: 'leads-recovery-reconsumos', target: 'Recovery', country: 'AUTO' },
};
const WEBHOOKS = {
  Leads:    'https://n8n.manzanaverde.la/webhook/0fa4fe5c-a553-4b33-98d3-96b406572118',
  Recovery: 'https://n8n.manzanaverde.la/webhook/48f220d5-0af8-4b6a-ae25-077d9f0c5d0a',
};

function extractFromContent(content) {
  if (!content) return null;
  const out = {};
  let m;
  m = content.match(/(?:Tel[ée]fono|Cel(?:ular)?|Phone|Whats(?:app)?)[:\*\s]+([+\d\s\-]{8,20}?)(?:[\*\n]|$)/i);
  if (m) {
    const digits = m[1].replace(/\D/g, '');
    if (digits.length >= 9 && digits.length <= 13) out.phone = digits;
  }
  if (!out.phone) {
    const m2 = content.match(/\b\+?\d{9,13}\b/g);
    if (m2) {
      const candidates = m2.filter(x => {
        const d = x.replace(/\D/g, '');
        return d.length >= 9 && d.length <= 13 && !/^(17|18|19|20)/.test(d);
      });
      if (candidates.length) {
        candidates.sort((a, b) => b.replace(/\D/g, '').length - a.replace(/\D/g, '').length);
        out.phone = candidates[0].replace(/\D/g, '');
      }
    }
  }
  m = content.match(/(?:Nombres?|Names?)[:\*\s]+([^\n*]+?)(?:\*|\n|$)/i);
  if (m) out.name = m[1].trim();
  m = content.match(/(?:Correo|Email)[:\*\s]+([\w._+-]+@[\w.-]+\.[\w]+)/i);
  if (m) out.email = m[1].trim();
  m = content.match(/Score[:\*\s]+([^\n*]+?)(?:\*|\n|$)/i);
  if (m) out.score = m[1].trim();
  m = content.match(/(?:Acci[óo]n|Action)[:\*\s]+([^\n*]+?)(?:\*|\n|$)/i);
  if (m) out.action = m[1].trim();
  m = content.match(/prioridad[:\*\s]+([A-Z]+)/i);
  if (m) out.priority = m[1];
  m = content.match(/\((https?:\/\/[^\s)]+)\)/);
  if (m) out.link = m[1];
  return out.phone ? out : null;
}
function normalizePhone(raw, country) {
  const d = String(raw||'').replace(/\D/g, '');
  if (country === 'PE') {
    if (d.length === 9 && d.startsWith('9')) return '51' + d;
    if (d.length === 11 && d.startsWith('51')) return d;
  }
  if (country === 'MX') {
    if (d.length === 10) return '52' + d;
    if (d.length === 12 && d.startsWith('52')) return d;
    if (d.length === 13 && d.startsWith('521')) return d;
  }
  if (country === 'CO') {
    if (d.length === 10 && d.startsWith('3')) return '57' + d;
    if (d.length === 12 && d.startsWith('57')) return d;
  }
  if (d.length === 11 && d.startsWith('51')) return d;
  if (d.length === 9 && d.startsWith('9')) return '51' + d;
  if (d.length === 12 && d.startsWith('52')) return d;
  if (d.length === 13 && d.startsWith('521')) return d;
  if (d.length === 12 && d.startsWith('57')) return d;
  if (d.length === 10 && d.startsWith('3')) return '57' + d;
  if (d.length === 10) return '52' + d;
  return d;
}
function detectCountry(phone) {
  const d = String(phone||'').replace(/\D/g, '');
  if (d.startsWith('51')) return 'PE';
  if (d.startsWith('52')) return 'MX';
  if (d.startsWith('57')) return 'CO';
  return 'UNKNOWN';
}
async function discordGet(url) {
  return await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: 'Bot ' + DISCORD_TOKEN }, json: true, timeout: 8000 });
