let recentPCLPhones = new Set();
const cacheTTLMs = 90 * 1000;
if (sd.dedupCache && (Date.now() - sd.dedupCache.ts) < cacheTTLMs) {
  recentPCLPhones = new Set(sd.dedupCache.phones);
} else {
  try {
    const cutoff = new Date(Date.now() - 2*60*1000).toISOString();
    const list = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://n8n.manzanaverde.la/api/v1/executions?workflowId=9MxNM5byLghh9ky2&limit=5&includeData=true',
      headers: { 'X-N8N-API-KEY': N8N_API_KEY },
      json: true,
      timeout: 8000,
    });
    const recent = (list.data || []).filter(e => e.startedAt >= cutoff);
    for (const exec of recent) {
      try {
        const rd = (exec.data && exec.data.resultData && exec.data.resultData.runData) || {};
        for (const trig of ['Leads','Recovery','Seguimiento','Webhook']) {
          if (rd[trig] && rd[trig][0]) {
            const body = rd[trig][0].data && rd[trig][0].data.main && rd[trig][0].data.main[0] && rd[trig][0].data.main[0][0] && rd[trig][0].data.main[0][0].json && rd[trig][0].data.main[0][0].json.body;
            if (body) {
              const raw = String(body.celular || body.phone || body.number || body.from || '').replace(/D/g, '');
              if (raw.length >= 9) recentPCLPhones.add(raw.slice(-9));
            }
          }
        }
      } catch (e) {}
    }
