const items = [];
const channelMaxMsgId = {}; // for cursor advance later
const channelInit = {};

const fetchResults = await Promise.all(Object.entries(CHANNELS).map(async ([channelId, conf]) => {
  const cursor = sd.cursors[channelId];
  if (!cursor) {
    try {
      const latest = await discordGet.call(this, 'https://discord.com/api/v10/channels/' + channelId + '/messages?limit=1');
      if (Array.isArray(latest) && latest.length > 0) sd.cursors[channelId] = latest[0].id;
      else sd.cursors[channelId] = '0';
    } catch (e) {}
    return { channelId, init: true, msgs: [] };
  }
  let messages = [];
  try {
    messages = await discordGet.call(this, 'https://discord.com/api/v10/channels/' + channelId + '/messages?limit=20');
  } catch (e) { return { channelId, error: e.message, msgs: [] }; }
  if (!Array.isArray(messages)) return { channelId, msgs: [] };
  return { channelId, msgs: messages };
}));

for (const r of fetchResults) {
  const conf = CHANNELS[r.channelId];
  if (r.init) { channelInit[r.channelId] = true; continue; }
  channelMaxMsgId[r.channelId] = sd.cursors[r.channelId];
  if (!r.msgs.length) continue;
  r.msgs.sort((a, b) => (a.id < b.id ? -1 : 1));
  const _windowMs = 3*60*1000;
  const _windowCutoff = new Date(Date.now() - _windowMs).toISOString();
  for (const msg of r.msgs) {
    if (msg.timestamp < _windowCutoff) continue;
    if (sd.cursors[r.channelId] && msg.id <= sd.cursors[r.channelId]) continue; // already processed // skip msgs older than 3 min
    if (msg.id > channelMaxMsgId[r.channelId]) channelMaxMsgId[r.channelId] = msg.id;
    if (msg.content && /#Error_ManyChat_Contactar_Usuario/i.test(msg.content)) continue;
    if (!msg.author || !msg.author.bot) continue;
    let text = msg.content || '';
    for (const e of (msg.embeds || [])) {
      text += '\n' + (e.title||'') + '\n' + (e.description||'');
      for (const f of (e.fields || [])) text += '\n' + (f.name||'') + ': ' + (f.value||'');
