    const phone = normalizePhone(ex.phone, conf.country);
    const phoneKey = String(phone).slice(-9);
    if (recentPCLPhones.has(phoneKey)) continue;
    const country = conf.country === 'AUTO' ? detectCountry(phone) : conf.country;
    items.push({
      json: {
        webhookUrl: WEBHOOKS[conf.target],
        channelId: r.channelId,
        msgId: msg.id,
        channel_name: conf.name,
        target: conf.target,
        payload: {
          celular: phone, email: ex.email || null, phone, pais: country,
          nombre: ex.name || 'Unknown', score: ex.score || null, priority: ex.priority || null,
          action: ex.action || null, link: ex.link || null, source: 'discord_bridge',
