const sd = $getWorkflowStaticData('global');
const items = $input.all();

const successByChannel = {}; // channelId -> max successful msgId
let totalProcessed = 0, totalErrors = 0;
const errorsList = [];

for (const it of items) {
  const j = it.json || {};
