  // n8n typically merges http response into json. We check by the original payload AND status of latest fields.
  // The previous node's response is in $json (same item). Look for statusCode or error markers.
  const sc = j.statusCode;
  const ok = (typeof sc === 'number' && sc >= 200 && sc < 300) || (j.body && (typeof j.body !== 'string' ? false : false)) || (sc === undefined && !j.error);
  if (sc >= 200 && sc < 300) {
    totalProcessed++;
    if (!successByChannel[channelId] || msgId > successByChannel[channelId]) successByChannel[channelId] = msgId;
  } else if (sc) {
    totalErrors++;
    errorsList.push({ channel: j.channel_name, msgId, status: sc });
  } else {
    // No statusCode means HTTP node didn't run? Treat as failed
    totalErrors++;
    errorsList.push({ channel: j.channel_name, msgId, status: 'no_response' });
  }
}

// Advance cursors only for channels with at least one success
for (const [chId, maxId] of Object.entries(successByChannel)) {
  if (!sd.cursors[chId] || maxId > sd.cursors[chId]) sd.cursors[chId] = maxId;
}

// Cleanup
delete sd._channelMaxSeen;

if (totalErrors > 0) {
  const ts = new Date().toISOString();
  return [{ json: { subject: 'Bridge: ' + totalErrors + ' error(s)', html: '<pre>' + JSON.stringify(errorsList, null, 2) + '</pre>', totalProcessed, totalErrors, errors: errorsList, timestamp: ts } }];
}
return [];

